import{_ as a}from"./chunks/architecture.DdIdPF_l.js";import{_ as o,o as t,c as i,a5 as s}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"Arquitetura do aplicativo e dos serviços","description":"","frontmatter":{"title":"Arquitetura do aplicativo e dos serviços","docId":"developer.architecture","translationKey":"developer.architecture","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","translationRevision":"76d290cbb6d1892a0e457838601c87bda882095e1bbde97d71b2e24249b4954a","order":30},"headers":[],"relativePath":"pt/developer/architecture.md","filePath":"pt/developer/architecture.md","lastUpdated":1794611623000}'),r={name:"pt/developer/architecture.md"};function d(n,e,c,l,p,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="application-and-service-architecture" tabindex="-1">Arquitetura do aplicativo e dos serviços <a class="header-anchor" href="#application-and-service-architecture" aria-label="Permalink to &quot;Arquitetura do aplicativo e dos serviços {#application-and-service-architecture}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Coloque uma alteração no serviço responsável por seu estado. Leia a <a href="./setup.html">configuração</a> e entenda a diferença entre um host existente e um host explicitamente independente. O desktop constrói um <code>AppCore</code>, envolve-o em um <code>ControlApi</code> e expõe essa instância à WebView, CLI local e agentes.</p><h2 id="trace-an-operation" tabindex="-1">Rastreie uma operação <a class="header-anchor" href="#trace-an-operation" aria-label="Permalink to &quot;Rastreie uma operação {#trace-an-operation}&quot;">​</a></h2><ol><li>Encontre o registro do método em <code>crates/tiktools-control-api/src/modules/</code>. O registro fornece esquemas, políticas e metadados de descoberta.</li><li>Siga o manipulador até <code>crates/tiktools-core/src/control/</code> e o serviço responsável. Coloque a validação de domínio e as mutações persistentes aqui, em vez de um adaptador de transporte.</li><li>Adicione o wrapper tipado em <code>crates/tiktools-client</code>; seu teste de paridade compara a cobertura do SDK com a superfície registrada.</li><li>Consuma o método por <code>src/web/shared/api/control-client.ts</code>. Entidades Vue mantêm estado de apresentação; o desktop não entrega à WebView um banco de dados nem um objeto de integração nativa.</li></ol><p>Winit é responsável pelo laço de eventos, Wry pela WebView e a integração da bandeja pela bandeja. <code>HostEmitter</code> e eventos de domínio levam valores serializados para fora do núcleo. O desktop encaminha trabalho por seu proxy do laço de eventos; a avaliação de scripts da WebView permanece nessa thread. Tokio executa operações assíncronas do host.</p><h2 id="concrete-boundary-check" tabindex="-1">Verificação concreta dos limites <a class="header-anchor" href="#concrete-boundary-check" aria-label="Permalink to &quot;Verificação concreta dos limites {#concrete-boundary-check}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>O primeiro comando verifica o cliente de frontend. O segundo executa diretamente o alvo de integração do SDK preservando o lockfile; flags de alvo do Cargo pertencem ao repasse <code>rust</code>, em vez da gramática mais restrita de testes específicos.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Todos os clientes observam a mesma operação autoritativa e o mesmo caminho de eventos. <code>host --ipc</code>, <code>host --stdio</code> e <code>--standalone</code> criam intencionalmente propriedade sem interface gráfica; comandos CLI normais se conectam a um proprietário em execução. O caminho legado <code>PageMessage</code>/<code>IpcRouter</code> permanece como código de compatibilidade e não deve receber novas variantes de mensagens.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Se dois clientes divergirem, compare identidade do host, diretório de dados, recursos de compilação e descoberta antes de adicionar outro store. Um plugin ausente é um problema de catálogo de execução, não um motivo para compilar sua implementação no núcleo. Documentos históricos de arquitetura contêm caminhos de frontend aposentados; siga o <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/lib.rs" target="_blank" rel="noreferrer">núcleo atual</a> e o <a href="./frontend.html">mapa do frontend</a> quando divergirem.</p><p><img src="`+a+'" alt="AppCore do TikTools, transporte, ControlClient e workspace Vue real"></p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>As features Cargo do binário escolhido definem os caminhos compilados. O núcleo habilita por padrão <code>native-plugins</code> e <code>napi-vm-node-api</code>; <code>persistence</code> fornece SQLite, <code>native-tiktok</code> o adaptador/entrada LIVE, e <code>plugin-install</code>, <code>cloud-auth</code>, <code>app-update</code> seus serviços. Confira <code>cargo tree -p tiktools-desktop -e features</code> (ou o CLI real) e depois <code>system.info</code>/discovery. Código compilado não comprova serviço configurado. Exercite entrada LIVE com a regressão <code>native-tiktok</code> em <a href="./performance.html">desempenho</a>.</p>',16)])])}const v=o(r,[["render",d]]);export{k as __pageData,v as default};
